import React, { useState } from 'react';
import CameraScanner from './CameraScanner';
import RiskMeter from './RiskMeter';
import Tesseract from 'tesseract.js';
import API from "./api";
import './style.css';

function App() {

  const [capturedImage, setCapturedImage] = useState("");
  const [ocrText, setOcrText] = useState("");
  const [riskScore, setRiskScore] = useState(0);
  const [detectedAdditives, setDetectedAdditives] = useState([]);
  const [loading, setLoading] = useState(false);

  const clearScan = () => {

    setCapturedImage("");
    setOcrText("");
    setRiskScore(0);
    setDetectedAdditives([]);
    setLoading(false);

  };

  const handleCapture = async (image) => {

    setCapturedImage(image);
    setLoading(true);

    try {

      console.log("Starting OCR...");

      const result = await Tesseract.recognize(
        image,
        "eng",
        {
          logger: m => console.log(m)
        }
      );

      const extractedText =
      result.data.text;

      console.log(
        "OCR Result:",
        extractedText
      );

      setOcrText(
        extractedText
      );

      // Send OCR text to backend

      const response =
      await API.post(
        "/analyze",
        {
          text: extractedText
        }
      );

      console.log(
        "Backend Response:",
        response.data
      );

      // Store additives

      setDetectedAdditives(
        response.data.detected_additives
      );

      // Use backend risk calculation
      // (includes +20 logic)

      setRiskScore(
        response.data.overall_risk_score
      );

    }

    catch(error){

      console.log(
        "Error:",
        error
      );

    }

    finally{

      setLoading(false);

    }

  };

  return (

<div className="app">

<header className="hero">

<h1>
<b>SAFE BITE</b>
</h1>

<p>
Scan food ingredients and detect harmful additives instantly
</p>

</header>

<div className="main-container">

<div className="left-side">

<CameraScanner
onCapture={handleCapture}
/>

{capturedImage && (

<div className="card">

<h2>
Captured Image
</h2>

<img
src={capturedImage}
alt="Captured"
width="100%"
/>

<div
style={{
marginTop:"15px"
}}
>

<button
onClick={clearScan}
>

Clear / Recapture

</button>

</div>

</div>

)}

<div className="card">

<h2>
OCR Result
</h2>

<p>

{
loading
?
"Scanning..."
:
ocrText ||
"No text detected yet..."
}

</p>

</div>

</div>

<div className="right-side">

<div className="card">

<h2>
Food Risk Meter
</h2>

<RiskMeter
score={riskScore}
/>

<p>

Overall Risk:

<b>
 {riskScore}%
</b>

</p>

</div>

<div className="card">

<h2>
Detected Additives
</h2>

{

detectedAdditives.length > 0

?

detectedAdditives.map(

(item,index)=>(

<div
className="ingredient-card"
key={index}
>

<div
className="ingredient-top"
>

<h3>

INS {item.code}

</h3>

<span
className="risk-badge"
>

{item.risk_score}%

</span>

</div>

<p>

<strong>
Name:
</strong>

{" "}

{item.name}

</p>

<p>

<strong>
Category:
</strong>

{" "}

{item.category}

</p>

<p>

<strong>
Description:
</strong>

{" "}

{item.description}

</p>

</div>

)

)

:

<p>
No additives detected
</p>

}

</div>

</div>

</div>

</div>

  );

}

export default App;
